// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;

    function setUp() public { c = new Roulette{value: 10 ether}(); }

    function testFuzz_property(uint256 warpDelta, address actor) public {
        vm.assume(actor != address(0) && actor != address(c));
        warpDelta = bound(warpDelta, 0, 1_000_000);

        // move time forward by fuzzed amount
        vm.warp(block.timestamp + warpDelta);
        uint256 t = block.timestamp;

        // first valid call at time t
        vm.deal(actor, 10 ether);
        vm.prank(actor);
        (bool ok1, ) = address(c).call{value: 10 ether}("");
        assertTrue(ok1, "first call should succeed");

        // second call at the SAME timestamp: must revert in the reference
        vm.deal(actor, 10 ether);
        vm.prank(actor);
        (bool ok2, ) = address(c).call{value: 10 ether}("");
        assertTrue(!ok2, "a second call at the same timestamp must fail");
    }
}
